#include "ringbuf.h"
#include <stdlib.h>

struct ringbuf {
    uint8_t *buf;
    size_t head;
    size_t tail;
    size_t size;
    size_t capacity;
};

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;

    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->head = 0;
    rb->tail = 0;
    rb->size = 0;
    rb->capacity = capacity;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || rb->size == rb->capacity)
        return 0;

    size_t avail = rb->capacity - rb->size;
    size_t written = len < avail ? len : avail;

    for (size_t i = 0; i < written; i++) {
        size_t pos = (rb->head + i) % rb->capacity;
        rb->buf[pos] = data[i];
    }
    rb->head = (rb->head + written) % rb->capacity;
    rb->size += written;

    return written;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || rb->size == 0)
        return 0;

    size_t rd = len < rb->size ? len : rb->size;

    for (size_t i = 0; i < rd; i++) {
        size_t pos = (rb->tail + i) % rb->capacity;
        out[i] = rb->buf[pos];
    }
    rb->tail = (rb->tail + rd) % rb->capacity;
    rb->size -= rd;

    return rd;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || rb->size == 0)
        return 0;

    size_t rd = len < rb->size ? len : rb->size;

    for (size_t i = 0; i < rd; i++) {
        size_t pos = (rb->tail + i) % rb->capacity;
        out[i] = rb->buf[pos];
    }

    return rd;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->size;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->size = 0;
}

#include <stdio.h>
#include <string.h>
#include "ringbuf.h"

int main(void)
{
    int passed = 0, failed = 0;

    /* Test 1: create & capacity */
    {
        ringbuf_t *rb = rb_create(8);
        if (!rb) { printf("FAIL: rb_create(8) == NULL\n"); failed++; goto _next; }
        if (rb_capacity(rb) != 8) { printf("FAIL: capacity != 8\n"); failed++; goto _next; }
        if (rb_size(rb) != 0) { printf("FAIL: size != 0 after create\n"); failed++; goto _next; }
        rb_destroy(rb);
        passed++;
    }

    /* Test 2: write then read round-trip */
    {
        uint8_t in[4] = {10, 20, 30, 40};
        uint8_t out[4];
        ringbuf_t *rb = rb_create(4);
        size_t w = rb_write(rb, in, 4);
        if (w != 4) { printf("FAIL: wrote %zu instead of 4\n", w); failed++; goto _next; }
        size_t r = rb_read(rb, out, 4);
        if (r != 4 || memcmp(out, in, 4)) { printf("FAIL: read mismatch round-trip\n"); failed++; goto _next; }
        rb_destroy(rb);
        passed++;
    }

    /* Test 3: wrap-around write */
    {
        uint8_t in[3] = {100, 200, 55};
        ringbuf_t *rb = rb_create(4);
        rb_write(rb, in, 3);   /* head=3, tail=0 */
        rb_read(rb, NULL, 2);   /* advance tail by 2 (using peek instead to not actually read) */
        uint8_t discard[2];
        rb_read(rb, discard, 2); /* tail now at 2 */
        /* Now write 4 bytes at head=3 -> wraps: positions 3,0,1,2 */
        uint8_t buf[5] = {1,2,3,4,5};
        size_t w = rb_write(rb, buf, 5);
        if (w != 4) { printf("FAIL: wrap-write returned %zu (expected 4)\n", w); failed++; goto _next; }
        /* Read back: should get the original 1 byte at head=3 position + 3 new */
        uint8_t out[4];
        rb_read(rb, out, 4);
        if (out[0]!=55 || out[1]!=1 || out[2]!=2 || out[3]!=3) { printf("FAIL: wrap-around data mismatch\n"); failed++; goto _next; }
        rb_destroy(rb);
        passed++;
    }

    /* Test 4: peek */
    {
        uint8_t in[3] = {5,6,7};
        ringbuf_t *rb = rb_create(8);
        rb_write(rb, in, 3);
        uint8_t out[3];
        size_t p = rb_peek(rb, out, 3);
        if (p != 3 || memcmp(out, in, 3)) { printf("FAIL: peek mismatch\n"); failed++; goto _next; }
        /* Size unchanged after peek */
        if (rb_size(rb) != 3) { printf("FAIL: peek should not change size\n"); failed++; goto _next; }
        rb_destroy(rb);
        passed++;
    }

    /* Test 5: NULL-safe helpers */
    {
        if (rb_create(0) != NULL)   { printf("FAIL: rb_create(0) should be NULL\n"); failed++; goto _next; }
        if (rb_size(NULL) != 0)      { printf("FAIL: rb_size(NULL)\n"); failed++; goto _next; }
        if (rb_capacity(NULL) != 0)  { printf("FAIL: rb_capacity(NULL)\n"); failed++; goto _next; }
        rb_destroy(NULL);             /* should not crash */
        rb_clear(NULL);               /* should not crash */
        uint8_t dummy = 0;
        if (rb_write(NULL, &dummy, 1) != 0) { printf("FAIL: write NULL rb\n"); failed++; goto _next; }
        if (rb_read(NULL, &dummy, 1) != 0){ printf("FAIL: read NULL rb\n"); failed++; goto _next; }
        if (rb_peek(NULL, &dummy, 1) != 0){ printf("FAIL: peek NULL rb\n"); failed++; goto _next; }
        passed++;
    }

    /* Test 6: ring buffer fully empty */
    {
        ringbuf_t *rb = rb_create(32);
        uint8_t in[32]; for(int i=0;i<32;i++) in[i]=(uint8_t)i;
        uint8_t out[16], peek_buf[16];
        /* Write 16, peek 16 */
        if (rb_write(rb, in, 16) != 16) { printf("FAIL: write 16\n"); failed++; goto _next; }
        size_t p = rb_peek(rb, peek_buf, 16);
        if (p!=16 || memcmp(peek_buf,in,16)!=0) { printf("FAIL: peek after partial write\n"); failed++; goto _next; }
        /* Read first 8 */
        if (rb_read(rb, out, 8) != 8){ printf("FAIL: read 8\n"); failed++;goto _next;}
        if (rb_size(rb)!=24){printf("FAIL: size after read\n");failed++;goto _next;}
        /* Write more to force wrap */
        uint8_t extra[4] = { 99,100,101,102 };
        rb_write(rb, in+16, 16);   /* fill remaining 16 slots, head wraps */
        /* Read first tail=8 bytes that were never overwritten + new data */
        uint8_t final[32];
        size_t r = rb_read(rb, final, 32);
        if (r!=32) { printf("FAIL: read all=%zu (expected 32)\n",r); failed++; goto _next; }
        rb_destroy(rb);
        passed++;
    }

    /* Test 7: rb_clear */
    {
        ringbuf_t *rb = rb_create(4);
        uint8_t d[4]={1,2,3,4};
        rb_write(rb,d,4);
        rb_read(rb,d,2); /* size=2, tail at 2 */
        rb_clear(rb);
        if (rb_size(rb)!=0) { printf("FAIL: clear not clearing\n"); failed++; goto _next; }
        if (rb_capacity(rb)!=4) { printf("FAIL: capacity changed after clear\n"); failed++; goto _next; }
        rb_destroy(rb);
        passed++;
    }

_next:
    printf("\n%d passed, %d failed\n", passed, failed);
    return failed > 0 ? 1 : 0;
}

